import fs from 'fs';
import path from 'path';
import matter from 'gray-matter';
import { marked } from 'marked';
import { Page, Frontmatter } from './types';
import { BuildCache } from './cache';

export function parseFile(filePath: string): Page {
  const raw = fs.readFileSync(filePath, 'utf-8');
  const { data, content } = matter(raw);

  let dateStr = '';
  if (data.date instanceof Date) {
    dateStr = data.date.toISOString().split('T')[0];
  } else if (typeof data.date === 'string') {
    dateStr = data.date;
  }

  const frontmatter: Frontmatter = {
    title: data.title || 'Untitled',
    date: dateStr,
    tags: Array.isArray(data.tags) ? data.tags : [],
    template: typeof data.template === 'string' ? data.template : undefined,
    layout: typeof data.layout === 'string' ? data.layout : undefined,
  };

  const html = marked.parse(content) as string;

  const slug = path.basename(filePath, '.md');

  return { frontmatter, html, slug };
}

export function parseDirectory(
  contentDir: string,
  cache?: BuildCache
): Page[] {
  if (!fs.existsSync(contentDir)) {
    return [];
  }

  const files = fs.readdirSync(contentDir).filter((f) => f.endsWith('.md'));

  const pages = files.map((file) => {
    const fullPath = path.join(contentDir, file);
    const slug = path.basename(file, '.md');

    if (cache && cache.isPopulated()) {
      const newHash = BuildCache.computeFileHash(fullPath);
      const cachedHash = cache.getContentHash(file);

      if (cachedHash === newHash && cache.getCachedPage(slug)) {
        cache.setContentHash(file, newHash);
        const cached = cache.getCachedPage(slug)!;
        return { ...cached.page };
      }
    }

    const page = parseFile(fullPath);
    return page;
  });

  return pages.sort((a, b) => {
    if (!a.frontmatter.date && !b.frontmatter.date) return 0;
    if (!a.frontmatter.date) return 1;
    if (!b.frontmatter.date) return -1;
    return b.frontmatter.date.localeCompare(a.frontmatter.date);
  });
}

import fs from 'fs';
import path from 'path';
import Handlebars from 'handlebars';
import { Page } from './types';
import { BuildCache } from './cache';

function htmlEncode(str: string): string {
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function wrapPage(title: string, body: string): string {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${htmlEncode(title)}</title>
  <style>
    body { font-family: system-ui, sans-serif; max-width: 800px; margin: 0 auto; padding: 2rem; line-height: 1.6; }
    a { color: #2563eb; }
    nav { margin-bottom: 2rem; }
    .meta { color: #6b7280; font-size: 0.9rem; margin-bottom: 1.5rem; }
    .tags { display: flex; gap: 0.5rem; flex-wrap: wrap; }
    .tag { background: #e5e7eb; padding: 0.2rem 0.6rem; border-radius: 4px; font-size: 0.85rem; }
  </style>
</head>
<body>
  <nav><a href="index.html">&larr; Home</a></nav>
  ${body}
</body>
</html>`;
}

function renderPageHtml(page: Page): string {
  const { title, date, tags } = page.frontmatter;
  const metaParts: string[] = [];
  if (date) metaParts.push(`<time>${htmlEncode(date)}</time>`);
  const meta = metaParts.length
    ? `<div class="meta">${metaParts.join(' &middot; ')}</div>`
    : '';

  const tagsHtml =
    tags && tags.length > 0
      ? `<div class="tags">${tags.map((t) => `<span class="tag">${htmlEncode(t)}</span>`).join('\n')}</div>`
      : '';

  const body = `<article>
  <h1>${htmlEncode(title)}</h1>
  ${meta}
  ${tagsHtml}
  ${page.html}
</article>`;

  return wrapPage(title, body);
}

function renderIndexHtml(pages: Page[]): string {
  const items = pages
    .map((p) => {
      const { title, date, tags } = p.frontmatter;
      const tagsHtml =
        tags && tags.length > 0
          ? ` <span class="tags">${tags.map((t) => `<span class="tag">${htmlEncode(t)}</span>`).join(' ')}</span>`
          : '';
      const dateHtml = date ? ` <time>${htmlEncode(date)}</time>` : '';
      return `<li>
      <a href="${htmlEncode(p.slug)}.html">${htmlEncode(title)}</a>${dateHtml}${tagsHtml}
    </li>`;
    })
    .join('\n');

  const body = `<h1>All Posts</h1>
  <ul>
    ${items}
  </ul>`;

  return wrapPage('Index', body);
}

interface TemplateEngine {
  renderPage(page: Page): string;
  renderIndex(pages: Page[]): string;
}

function registerPartials(partialsDir: string): void {
  if (!fs.existsSync(partialsDir)) return;
  const files = fs.readdirSync(partialsDir).filter((f) => f.endsWith('.hbs'));
  for (const file of files) {
    const name = path.basename(file, '.hbs');
    const content = fs.readFileSync(path.join(partialsDir, file), 'utf-8');
    Handlebars.registerPartial(name, content);
  }
}

function loadTemplates(templateDir: string): TemplateEngine | null {
  if (!fs.existsSync(templateDir)) return null;

  const partialsDir = path.join(templateDir, 'partials');
  registerPartials(partialsDir);

  const layoutsDir = path.join(templateDir, 'layouts');
  const layouts = new Map<string, Handlebars.TemplateDelegate>();
  if (fs.existsSync(layoutsDir)) {
    const files = fs.readdirSync(layoutsDir).filter((f) => f.endsWith('.hbs'));
    for (const file of files) {
      const name = path.basename(file, '.hbs');
      const content = fs.readFileSync(path.join(layoutsDir, file), 'utf-8');
      layouts.set(name, Handlebars.compile(content));
    }
  }

  const pageTemplates = new Map<string, Handlebars.TemplateDelegate>();
  const files = fs.readdirSync(templateDir).filter((f) => f.endsWith('.hbs'));
  for (const file of files) {
    const name = path.basename(file, '.hbs');
    const content = fs.readFileSync(path.join(templateDir, file), 'utf-8');
    pageTemplates.set(name, Handlebars.compile(content));
  }

  return {
    renderPage(page: Page): string {
      const templateName = page.frontmatter.template || 'page';
      const template =
        pageTemplates.get(templateName) || pageTemplates.get('page');
      if (!template) {
        throw new Error(`Page template "${templateName}" not found`);
      }

      const layoutName = page.frontmatter.layout || 'default';
      const layout =
        layouts.get(layoutName) || layouts.get('default');

      const body = template({
        title: page.frontmatter.title,
        date: page.frontmatter.date,
        tags: page.frontmatter.tags || [],
        content: page.html,
        slug: page.slug,
      });

      if (layout) {
        return layout({
          title: page.frontmatter.title,
          body,
        });
      }

      return body;
    },

    renderIndex(pages: Page[]): string {
      const hasIndex = pageTemplates.has('index');
      if (!hasIndex) {
        return renderIndexHtml(pages);
      }

      const template = pageTemplates.get('index')!;
      const layout = layouts.get('default');

      const body = template({
        pages: pages.map((p) => ({
          title: p.frontmatter.title,
          date: p.frontmatter.date,
          tags: p.frontmatter.tags || [],
          slug: p.slug,
        })),
      });

      if (layout) {
        return layout({ title: 'Index', body });
      }

      return body;
    },
  };
}

export function generateSite(
  pages: Page[],
  outputDir: string,
  templateDir?: string,
  cache?: BuildCache
): void {
  const engine = templateDir ? loadTemplates(templateDir) : null;

  fs.mkdirSync(outputDir, { recursive: true });

  for (const page of pages) {
    let html: string;
    const slug = page.slug;

    if (cache && cache.isPopulated()) {
      const currentTemplateHash = templateDir
        ? BuildCache.computeTemplateHash(templateDir)
        : '';

      const cachedTemplateHash = cache.getTemplateHash();
      const cached = cache.getCachedPage(slug);

      if (
        cached &&
        currentTemplateHash === cachedTemplateHash &&
        currentTemplateHash !== ''
      ) {
        html = cached.html;
      } else {
        html = engine ? engine.renderPage(page) : renderPageHtml(page);
        cache.setCachedPage(slug, { page, html });
      }
    } else {
      html = engine ? engine.renderPage(page) : renderPageHtml(page);
      if (cache) {
        cache.setCachedPage(slug, { page, html });
      }
    }

    fs.writeFileSync(path.join(outputDir, `${slug}.html`), html, 'utf-8');
  }

  if (cache && cache.isPopulated()) {
    const indexFromCache = cache.getIndexHtml();
    const currentTemplateHash = templateDir
      ? BuildCache.computeTemplateHash(templateDir)
      : '';

    if (
      indexFromCache &&
      currentTemplateHash === cache.getTemplateHash() &&
      currentTemplateHash !== ''
    ) {
      fs.writeFileSync(
        path.join(outputDir, 'index.html'),
        indexFromCache,
        'utf-8'
      );
      return;
    }
  }

  const indexHtml = engine
    ? engine.renderIndex(pages)
    : renderIndexHtml(pages);
  fs.writeFileSync(path.join(outputDir, 'index.html'), indexHtml, 'utf-8');

  if (cache) {
    cache.setIndexHtml(indexHtml);
    if (templateDir) {
      cache.setTemplateHash(BuildCache.computeTemplateHash(templateDir));
    }
  }
}

import { Page } from './types';
import { Plugin, PluginContext, SSGOptions } from './plugin';
import { BuildCache, BuildStats } from './cache';
import { DevServerPlugin, ServerInstance } from './plugins/devserver';

export class SSGEngine {
  private plugins: Plugin[] = [];
  private context: PluginContext;
  private cache: BuildCache;

  constructor(options: SSGOptions) {
    this.cache = new BuildCache('.ssg-cache.json');
    this.context = {
      pages: [],
      options,
      cache: this.cache,
      stats: { pagesBuilt: 0, pagesSkipped: 0, timeSavedMs: 0 },
    };
  }

  get pages(): Page[] {
    return this.context.pages;
  }

  get stats(): BuildStats | undefined {
    return this.context.stats;
  }

  register(plugin: Plugin): void {
    this.plugins.push(plugin);
  }

  async build(): Promise<void> {
    const startTime = Date.now();
    const options = this.context.options;

    if (options.clean) {
      this.cache.clear();
    } else if (options.incremental) {
      this.cache.load();
    }

    await this.runHook('onStart');
    await this.runHook('beforeBuild');

    for (let i = 0; i < this.context.pages.length; i++) {
      this.context.pages[i] = await this.runOnFile(this.context.pages[i]);
    }

    await this.runHook('afterBuild');

    if (options.incremental || options.clean) {
      this.cache.save();
    }

    const elapsed = Date.now() - startTime;

    if (this.context.stats && options.incremental) {
      this.context.stats.timeSavedMs = elapsed;
      console.log(
        `Site generated: ${this.context.stats.pagesBuilt} pages built, ` +
          `${this.context.stats.pagesSkipped} pages skipped`
      );
    }
  }

  async serve(): Promise<ServerInstance> {
    await this.runHook('onStart');
    await this.runBuildPipeline();

    const devPlugin = this.plugins.find(
      (p) => p.name === 'devserver'
    ) as DevServerPlugin;
    if (!devPlugin) {
      throw new Error(
        'DevServerPlugin is required for serving but was not registered'
      );
    }

    const rebuildFn = async () => {
      await this.runBuildPipeline();
    };

    return devPlugin.startServer(this.context, rebuildFn);
  }

  async shutdown(): Promise<void> {
    await this.runHook('onEnd');
  }

  private async runBuildPipeline(): Promise<void> {
    await this.runHook('beforeBuild');

    for (let i = 0; i < this.context.pages.length; i++) {
      this.context.pages[i] = await this.runOnFile(this.context.pages[i]);
    }

    await this.runHook('afterBuild');

    console.log(`Site rebuilt (${this.context.pages.length} pages)`);
  }

  private async runHook(
    hook: 'onStart' | 'beforeBuild' | 'afterBuild' | 'onEnd'
  ): Promise<void> {
    for (const plugin of this.plugins) {
      const fn = plugin[hook] as
        | ((context: PluginContext) => void | Promise<void>)
        | undefined;
      if (fn) {
        await fn(this.context);
      }
    }
  }

  private async runOnFile(page: Page): Promise<Page> {
    let result = page;
    for (const plugin of this.plugins) {
      if (plugin.onFile) {
        result = await plugin.onFile(result);
      }
    }
    return result;
  }
}

#!/usr/bin/env node

import path from 'path';
import { SSGEngine } from './engine';
import { MarkdownPlugin } from './plugins/markdown';
import { TemplatePlugin } from './plugins/template';
import { DevServerPlugin } from './plugins/devserver';
import { Plugin, SSGOptions } from './plugin';

function getDefaultPlugins(): Plugin[] {
  return [
    new MarkdownPlugin(),
    new TemplatePlugin(),
    new DevServerPlugin(),
  ];
}

function loadConfigPlugins(cwd: string): Plugin[] {
  try {
    const configPath = path.resolve(cwd, 'ssg.config.js');
    const config = require(configPath);
    if (config && Array.isArray(config.plugins)) {
      return config.plugins;
    }
    if (config && config.default && Array.isArray(config.default.plugins)) {
      return config.default.plugins;
    }
  } catch {
    // config file not found or invalid, use defaults
  }
  return getDefaultPlugins();
}

function parseArgs(args: string[]): {
  content: string;
  output: string;
  templates: string;
  port: number;
  incremental: boolean;
  clean: boolean;
} {
  let content = 'content';
  let output = 'dist';
  let templates = 'templates';
  let port = 3000;
  let incremental = false;
  let clean = false;
  let i = 0;

  while (i < args.length) {
    if (args[i] === '--content' && i + 1 < args.length) {
      content = args[i + 1];
      i += 2;
    } else if (args[i] === '--output' && i + 1 < args.length) {
      output = args[i + 1];
      i += 2;
    } else if (args[i] === '--templates' && i + 1 < args.length) {
      templates = args[i + 1];
      i += 2;
    } else if (args[i] === '--port' && i + 1 < args.length) {
      port = parseInt(args[i + 1], 10);
      i += 2;
    } else if (args[i] === '--incremental') {
      incremental = true;
      i++;
    } else if (args[i] === '--clean') {
      clean = true;
      i++;
    } else {
      i++;
    }
  }

  return { content, output, templates, port, incremental, clean };
}

const command = process.argv[2];

async function main(): Promise<void> {
  if (command === 'build') {
    const {
      content,
      output,
      templates,
      incremental,
      clean,
    } = parseArgs(process.argv.slice(3));
    const plugins = loadConfigPlugins(process.cwd());

    const options: SSGOptions = {
      content,
      output,
      templates,
      port: 3000,
      incremental,
      clean,
    };

    const engine = new SSGEngine(options);
    for (const plugin of plugins) {
      engine.register(plugin);
    }

    await engine.build();
    if (!incremental) {
      console.log(`Site generated in ${output} (${engine.pages.length} pages)`);
    }
  } else if (command === 'serve') {
    const { content, output, templates, port } = parseArgs(
      process.argv.slice(3)
    );
    const plugins = loadConfigPlugins(process.cwd());

    const options: SSGOptions = { content, output, templates, port };

    const engine = new SSGEngine(options);
    for (const plugin of plugins) {
      engine.register(plugin);
    }

    const pages = engine.pages;
    await engine.build();
    console.log(`Site generated in ${output} (${pages.length} pages)`);

    await engine.serve();
  } else {
    console.log(
      'Usage: npx ssg build [--content <dir>] [--output <dir>] [--templates <dir>]\n' +
        '       npx ssg serve [--content <dir>] [--output <dir>] [--templates <dir>] [--port <port>]'
    );
    process.exit(command ? 1 : 0);
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

import { parseDirectory } from '../parser';
import { Plugin, PluginContext } from '../plugin';

export class MarkdownPlugin implements Plugin {
  name = 'markdown';

  beforeBuild(context: PluginContext): void {
    const beforeCount = context.pages.length;
    context.pages = parseDirectory(context.options.content, context.cache);
    const afterCount = context.pages.length;

    if (context.stats && context.cache && context.cache.isPopulated()) {
      const parsed = context.pages.length;
      const skipped = beforeCount > 0 ? Math.max(0, beforeCount - (afterCount - beforeCount)) : 0;
      context.stats.pagesSkipped = 0;
    }
  }
}

import fs from 'fs';
import path from 'path';
import matter from 'gray-matter';
import { marked } from 'marked';
import { Page, Frontmatter } from './types';
import { BuildCache } from './cache';

export function parseFile(filePath: string): Page {
  const raw = fs.readFileSync(filePath, 'utf-8');
  const { data, content } = matter(raw);

  let dateStr = '';
  if (data.date instanceof Date) {
    dateStr = data.date.toISOString().split('T')[0];
  } else if (typeof data.date === 'string') {
    dateStr = data.date;
  }

  const frontmatter: Frontmatter = {
    title: data.title || 'Untitled',
    date: dateStr,
    tags: Array.isArray(data.tags) ? data.tags : [],
    template: typeof data.template === 'string' ? data.template : undefined,
    layout: typeof data.layout === 'string' ? data.layout : undefined,
  };

  const html = marked.parse(content) as string;

  const slug = path.basename(filePath, '.md');

  return { frontmatter, html, slug };
}

export interface ParseStats {
  parsed: number;
  skipped: number;
}

export function parseDirectory(
  contentDir: string,
  cache?: BuildCache,
  stats?: ParseStats
): Page[] {
  if (!fs.existsSync(contentDir)) {
    return [];
  }

  const files = fs.readdirSync(contentDir).filter((f) => f.endsWith('.md'));

  const pages = files.map((file) => {
    const fullPath = path.join(contentDir, file);
    const slug = path.basename(file, '.md');

    if (cache && cache.isPopulated()) {
      const newHash = BuildCache.computeFileHash(fullPath);
      const cachedHash = cache.getContentHash(file);

      if (cachedHash === newHash && cache.getCachedPage(slug)) {
        if (stats) stats.skipped++;
        cache.setContentHash(file, newHash);
        const cached = cache.getCachedPage(slug)!;
        return { ...cached.page };
      }

      cache.setContentHash(file, newHash);
    }

    if (stats) stats.parsed++;
    const page = parseFile(fullPath);
    return page;
  });

  return pages.sort((a, b) => {
    if (!a.frontmatter.date && !b.frontmatter.date) return 0;
    if (!a.frontmatter.date) return 1;
    if (!b.frontmatter.date) return -1;
    return b.frontmatter.date.localeCompare(a.frontmatter.date);
  });
}

import fs from 'fs';
import path from 'path';
import Handlebars from 'handlebars';
import { Page } from './types';
import { BuildCache } from './cache';

function htmlEncode(str: string): string {
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function wrapPage(title: string, body: string): string {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${htmlEncode(title)}</title>
  <style>
    body { font-family: system-ui, sans-serif; max-width: 800px; margin: 0 auto; padding: 2rem; line-height: 1.6; }
    a { color: #2563eb; }
    nav { margin-bottom: 2rem; }
    .meta { color: #6b7280; font-size: 0.9rem; margin-bottom: 1.5rem; }
    .tags { display: flex; gap: 0.5rem; flex-wrap: wrap; }
    .tag { background: #e5e7eb; padding: 0.2rem 0.6rem; border-radius: 4px; font-size: 0.85rem; }
  </style>
</head>
<body>
  <nav><a href="index.html">&larr; Home</a></nav>
  ${body}
</body>
</html>`;
}

function renderPageHtml(page: Page): string {
  const { title, date, tags } = page.frontmatter;
  const metaParts: string[] = [];
  if (date) metaParts.push(`<time>${htmlEncode(date)}</time>`);
  const meta = metaParts.length
    ? `<div class="meta">${metaParts.join(' &middot; ')}</div>`
    : '';

  const tagsHtml =
    tags && tags.length > 0
      ? `<div class="tags">${tags.map((t) => `<span class="tag">${htmlEncode(t)}</span>`).join('\n')}</div>`
      : '';

  const body = `<article>
  <h1>${htmlEncode(title)}</h1>
  ${meta}
  ${tagsHtml}
  ${page.html}
</article>`;

  return wrapPage(title, body);
}

function renderIndexHtml(pages: Page[]): string {
  const items = pages
    .map((p) => {
      const { title, date, tags } = p.frontmatter;
      const tagsHtml =
        tags && tags.length > 0
          ? ` <span class="tags">${tags.map((t) => `<span class="tag">${htmlEncode(t)}</span>`).join(' ')}</span>`
          : '';
      const dateHtml = date ? ` <time>${htmlEncode(date)}</time>` : '';
      return `<li>
      <a href="${htmlEncode(p.slug)}.html">${htmlEncode(title)}</a>${dateHtml}${tagsHtml}
    </li>`;
    })
    .join('\n');

  const body = `<h1>All Posts</h1>
  <ul>
    ${items}
  </ul>`;

  return wrapPage('Index', body);
}

interface TemplateEngine {
  renderPage(page: Page): string;
  renderIndex(pages: Page[]): string;
}

function registerPartials(partialsDir: string): void {
  if (!fs.existsSync(partialsDir)) return;
  const files = fs.readdirSync(partialsDir).filter((f) => f.endsWith('.hbs'));
  for (const file of files) {
    const name = path.basename(file, '.hbs');
    const content = fs.readFileSync(path.join(partialsDir, file), 'utf-8');
    Handlebars.registerPartial(name, content);
  }
}

function loadTemplates(templateDir: string): TemplateEngine | null {
  if (!fs.existsSync(templateDir)) return null;

  const partialsDir = path.join(templateDir, 'partials');
  registerPartials(partialsDir);

  const layoutsDir = path.join(templateDir, 'layouts');
  const layouts = new Map<string, Handlebars.TemplateDelegate>();
  if (fs.existsSync(layoutsDir)) {
    const files = fs.readdirSync(layoutsDir).filter((f) => f.endsWith('.hbs'));
    for (const file of files) {
      const name = path.basename(file, '.hbs');
      const content = fs.readFileSync(path.join(layoutsDir, file), 'utf-8');
      layouts.set(name, Handlebars.compile(content));
    }
  }

  const pageTemplates = new Map<string, Handlebars.TemplateDelegate>();
  const files = fs.readdirSync(templateDir).filter((f) => f.endsWith('.hbs'));
  for (const file of files) {
    const name = path.basename(file, '.hbs');
    const content = fs.readFileSync(path.join(templateDir, file), 'utf-8');
    pageTemplates.set(name, Handlebars.compile(content));
  }

  return {
    renderPage(page: Page): string {
      const templateName = page.frontmatter.template || 'page';
      const template =
        pageTemplates.get(templateName) || pageTemplates.get('page');
      if (!template) {
        throw new Error(`Page template "${templateName}" not found`);
      }

      const layoutName = page.frontmatter.layout || 'default';
      const layout =
        layouts.get(layoutName) || layouts.get('default');

      const body = template({
        title: page.frontmatter.title,
        date: page.frontmatter.date,
        tags: page.frontmatter.tags || [],
        content: page.html,
        slug: page.slug,
      });

      if (layout) {
        return layout({
          title: page.frontmatter.title,
          body,
        });
      }

      return body;
    },

    renderIndex(pages: Page[]): string {
      const hasIndex = pageTemplates.has('index');
      if (!hasIndex) {
        return renderIndexHtml(pages);
      }

      const template = pageTemplates.get('index')!;
      const layout = layouts.get('default');

      const body = template({
        pages: pages.map((p) => ({
          title: p.frontmatter.title,
          date: p.frontmatter.date,
          tags: p.frontmatter.tags || [],
          slug: p.slug,
        })),
      });

      if (layout) {
        return layout({ title: 'Index', body });
      }

      return body;
    },
  };
}

export interface GenerateStats {
  built: number;
  skipped: number;
}

export function generateSite(
  pages: Page[],
  outputDir: string,
  templateDir?: string,
  cache?: BuildCache,
  stats?: GenerateStats
): void {
  const engine = templateDir ? loadTemplates(templateDir) : null;

  fs.mkdirSync(outputDir, { recursive: true });

  const currentTemplateHash = templateDir
    ? BuildCache.computeTemplateHash(templateDir)
    : '';

  const cachePopulated = cache && cache.isPopulated();
  const cachedTemplateHash = cache ? cache.getTemplateHash() : '';

  for (const page of pages) {
    let html: string;
    const slug = page.slug;

    if (
      cachePopulated &&
      currentTemplateHash === cachedTemplateHash &&
      currentTemplateHash !== '' &&
      cache!.getCachedPage(slug)
    ) {
      html = cache!.getCachedPage(slug)!.html;
      if (stats) stats.skipped++;
    } else {
      html = engine ? engine.renderPage(page) : renderPageHtml(page);
      if (stats) stats.built++;
      if (cache) {
        cache.setCachedPage(slug, { page, html });
      }
    }

    fs.writeFileSync(path.join(outputDir, `${slug}.html`), html, 'utf-8');
  }

  if (cache) {
    cache.setTemplateHash(currentTemplateHash);
  }

  if (
    cachePopulated &&
    currentTemplateHash === cachedTemplateHash &&
    currentTemplateHash !== '' &&
    cache!.getIndexHtml()
  ) {
    fs.writeFileSync(
      path.join(outputDir, 'index.html'),
      cache!.getIndexHtml()!,
      'utf-8'
    );
  } else {
    const indexHtml = engine
      ? engine.renderIndex(pages)
      : renderIndexHtml(pages);
    fs.writeFileSync(path.join(outputDir, 'index.html'), indexHtml, 'utf-8');

    if (cache) {
      cache.setIndexHtml(indexHtml);
    }
  }
}

import { parseDirectory, ParseStats } from '../parser';
import { Plugin, PluginContext } from '../plugin';

export class MarkdownPlugin implements Plugin {
  name = 'markdown';

  beforeBuild(context: PluginContext): void {
    const parseStats: ParseStats = { parsed: 0, skipped: 0 };
    context.pages = parseDirectory(
      context.options.content,
      context.cache,
      parseStats
    );
  }
}

import { generateSite, GenerateStats } from '../generator';
import { Plugin, PluginContext } from '../plugin';

export class TemplatePlugin implements Plugin {
  name = 'template';

  afterBuild(context: PluginContext): void {
    const genStats: GenerateStats = { built: 0, skipped: 0 };
    const hasCache = context.cache && context.cache.isPopulated();

    generateSite(
      context.pages,
      context.options.output,
      context.options.templates,
      context.cache,
      genStats
    );

    if (context.stats && hasCache) {
      context.stats.pagesBuilt = genStats.built;
      context.stats.pagesSkipped = genStats.skipped;
    } else if (context.stats) {
      context.stats.pagesBuilt = genStats.built;
      context.stats.pagesSkipped = 0;
    }
  }
}

